INSERT INTO profession_details (profession_id, reality, pros, cons) VALUES
(142, 'Не "маг чисел". Это 80% рутины, 15% "а почему не сходится?", и 5% "ура, сдал отчёт!". И налоговая — всегда стресс.', '["Порядок — это сила", "Востребовано всегда", "Стабильность", "Можно работать в любой сфере"]', '["80% рутины", "Налоговая — стресс", "Ответственность — ошибка = штраф", "Квартал — ночи в офисе", "Выгорание через 5 лет"]'),
(143, 'Не "шериф, который всё знает". Это 70% проверок, 20% отчётов, и 10% конфликтов. И проверяемые врут — всегда.', '["Порядок — это сила", "Видишь результат — нашёл нарушение", "Уважение (или страх)", "Можно работать в любой сфере"]', '["70% проверок", "Конфликты — норма", "Проверяемые врут", "Ответственность — ошибка = репутация", "Выгорание через 5 лет"]'),
(144, 'Не "королева офиса". Это 50% рутины, 30% организации, и 20% "а вдруг начальство приедет?". И никто не ценит — пока что-то не сломается.', '["Офис — твоя вотчина", "Видишь результат", "Стабильность", "Можно работать в любой сфере"]', '["50% рутины", "Никто не ценит", "Зарплата на старте низкая", "Начальство приедет — паника", "Выгорание через 5 лет"]'),
(145, 'Не "финансовый гуру". Это 90% рутины, 5% конфликтов, и 5% "спасибо" (редкость). И ответственность за деньги — всегда.', '["Стабильность", "Социальный пакет", "Каждый день понятный", "Можно работать в любой точке"]', '["90% рутины", "Клиенты агрессивные", "Ответственность за деньги", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(146, 'Не "хранитель мудрости веков". Это 70% каталогизации, 20% поиска ("где этот документ?"), и 10% чтения. И тишина — иногда гнетёт.', '["Тишина — порядок", "Каждый день понятный", "Можно читать (иногда)", "Стабильность — всегда нужны"]', '["70% каталогизации", "Тишина гнетёт", "Зарплата — смешная", "Никто не ценит", "Выгорание через 5 лет"]'),
(147, 'Не "игра целый день". Это 80% одного и того же теста, 15% "баг не воспроизводится", и 5% "нашёл! Критический!".', '["Порядок — это сила", "Виден результат — продукт стабилен", "Можно работать в любой сфере", "Удалёнка — норма"]', '["80% рутины", "Баг не воспроизводится", "Разработчики игнорируют", "Выгорание через 3 года", "Замена автотестами"]'),
(148, 'Не "юрист из кино". Это 80% бумаг (договоры, акты), 15% "клиент опоздал", и 5% "подпись поставлена".', '["Стабильность", "Уважение в обществе", "Можно свой кабинет", "Каждый день понятный"]', '["80% бумаг", "Клиенты опаздывают", "Ответственность — ошибка = суд", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(149, 'Не "правая рука босса". Это 60% планирования, 30% "он снова передумал", и 10% "вот идеальный день".', '["Видишь изнутри", "Стабильность", "Можно перейти в HR/менеджмент", "Каждый день новое"]', '["60% планирования", "Босс передумал — опять", "Зарплата на старте низкая", "Никто не ценит", "Выгорание через 3 года"]'),
(150, 'Не "хранитель склада". Это 70% ходьбы, 20% "где эта коробка?", и 10% "инвентаризация совпала!".', '["Порядок — это сила", "Виден результат — всё на местах", "Физическая форма", "Можно работать в любой сфере"]', '["70% ходьбы", "Где эта коробка?", "Физический труд", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(151, 'Не "бумажный тигр". Это 80% реестров, 15% "а вдруг потерял?", и 5% "всё в порядке!".', '["Порядок — это сила", "Стабильность", "Можно работать в госучреждениях", "Каждый день понятный"]', '["80% реестров", "А вдруг потерял?", "Зарплата — смешная", "Бюрократия давит", "Выгорание через 5 лет"]'),
(152, 'Не "волшебник рисков". Это 70% Excel, 20% "а вдруг не угадал?", и 10% "резерв хватит!".', '["Математика = власть", "Высокий статус", "Можно в любую сферу", "Стабильность — всегда нужны"]', '["70% Excel", "Ошибка = миллионы", "Бюрократия", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(153, 'Не "пограничник из фильма". Это 80% проверок документов, 15% "а вдруг контрабанда?", и 5% "задержание!".', '["Служишь стране", "Стабильность", "Льготы, пенсия", "Каждый день понятный"]', '["80% документов", "Скука", "Дежурства", "Конфликты — норма", "Выгорание через 5 лет"]'),
(154, 'Не "детектив из сериала". Это 60% бумаг, 30% "свидетель молчит", и 10% "вот оно — улика!".', '["Порядок = справедливость", "Виден результат — дело раскрыто", "Можно перейти в юриспруденцию", "Стабильность"]', '["60% бумаг", "Свидетель молчит", "Опасность — преступники", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(155, 'Не "дипломат из кино". Это 70% протокола, 20% "а вдруг оскорбил?", и 10% "переговоры успешны!".', '["Служишь стране", "Видишь мир", "Стабильность", "Уважение в обществе"]', '["70% протокола", "Оскорбил — скандал", "Дежурства", "Отлучки от семьи", "Выгорание через 5 лет"]'),
(156, 'Не "фемида". Это 80% дел, 15% "а вдруг взятка?", и 5% "приговор оглашён!".', '["Справедливость = смысл", "Высокий статус", "Стабильность", "Уважение в обществе"]', '["80% дел", "Взятки — искушение", "Ответственность — жизни", "Дежурства", "Выгорание через 5 лет"]'),
(157, 'Не "военный юрист". Это 70% регламентов, 20% "а вдруг не по уставу?", и 10% "всё по закону!".', '["Служишь стране", "Стабильность", "Льготы, пенсия", "Каждый день понятный"]', '["70% регламентов", "Иерархия давит", "Зарплата — смешная", "Бюрократия", "Выгорание через 5 лет"]'),
(158, 'Не "волшебник цифр". Это 80% таблиц, 15% "а вдруг ошибка?", и 5% "прогноз сбылся!".', '["Математика = власть", "Можно в любую сферу", "Стабильность", "Удалёнка — норма"]', '["80% таблиц", "Ошибка = позор", "Зарплата на старте низкая", "Бюрократия", "Выгорание через 5 лет"]'),
(159, 'Не "волшебник стандартов". Это 70% проверок, 20% "а вдруг не соответствует?", и 10% "сертификат выдан!".', '["Порядок = качество", "Можно в любую сферу", "Стабильность", "Каждый день понятный"]', '["70% проверок", "А вдруг не соответствует?", "Зарплата на старте низкая", "Бюрократия", "Выгорание через 5 лет"]'),
(160, 'Не "маг сетей". Это 70% мониторинга, 20% "а вдруг упало?", и 10% "всё работает!".', '["Порядок = связь", "Можно в любую сферу", "Стабильность", "Удалёнка — норма"]', '["70% мониторинга", "А вдруг упало — ночью", "Дежурства", "Зарплата на старте низкая", "Выгорание через 5 лет"]');
